  let v: vec4f = u.d[slot / 4];
  let comp: i32 = slot % 4;
  let f: f32 = select(select(select(v.x, v.y, comp == 1), v.z, comp == 2), v.w, comp == 3);
  let raw: i32 = i32(f + 0.5);
