  let lx: f32 = (p.x - origin.x) / adv;
  let ly: f32 = (origin.y - p.y) / size;
  let idx: i32 = i32(floor(lx));
  let inside: bool = (lx >= 0.0) && (ly >= 0.0) && (ly <= 1.0) && (idx < s.y);
  let real: i32 = charAt(s.x + clamp(idx, 0, max(s.y - 1, 0)));
